$bytes = [System.IO.File]::ReadAllBytes($p)
$txt = $gbk.GetString($bytes)
if (-not ([Convert]::ToBase64String($bytes) -eq [Convert]::ToBase64String($gbk.GetBytes($txt)))) { Write-Host 'ABORT: not clean GBK'; exit 1 }

$parts = $txt.Split([string[]]@("`r`n"), [System.StringSplitOptions]::None)
$lines = New-Object System.Collections.Generic.List[string]
$lines.AddRange([string[]]$parts)

$changed = 0
# 1) 菜单行（含 [A]，且只有它含 '[A]'；其唯一数字就是那个 5）
for ($i=0; $i -lt $lines.Count; $i++) {
  if ($lines[$i].Contains('[A]')) { $lines[$i] = $lines[$i].Replace('5','30'); $changed++ }
}
# 2) :fullloop 块内第一条 echo === 行
$fi = -1
for ($i=0; $i -lt $lines.Count; $i++) { if ($lines[$i].Trim() -eq ':fullloop') { $fi = $i; break } }
if ($fi -ge 0) {
  for ($j=$fi; $j -lt $lines.Count; $j++) {
    if ($lines[$j].StartsWith('echo ===')) { $lines[$j] = $lines[$j].Replace('5','30'); $changed++; break }
  }
}
$joined = [string]::Join("`r`n", $lines)
[System.IO.File]::WriteAllBytes($p, $gbk.GetBytes($joined))

$b2 = [System.IO.File]::ReadAllBytes($p)
$t2 = $gbk.GetString($b2)
Write-Host ("lines changed     : " + $changed)
Write-Host ("GBK-lossless      : " + ([Convert]::ToBase64String($b2) -eq [Convert]::ToBase64String($gbk.GetBytes($t2))))
Write-Host ("no U+FFFD         : " + (-not $t2.Contains([char]0xFFFD)))
Write-Host ("has [A]/fullloop   : " + ($t2.Contains('[A]') -and $t2.Contains(':fullloop') -and $t2.Contains('full_loop.py')))

$err = "$env:TEMP\gui_err.txt"; $out = "$env:TEMP\gui_out.txt"
$p = Start-Process -FilePath "python" -ArgumentList "gui.py" -WorkingDirectory "E:\project\海外仓\automation" -PassThru -RedirectStandardError $err -RedirectStandardOutput $out
Start-Sleep -Seconds 3
if ($p.HasExited) {
  Write-Host "CRASHED exit=$($p.ExitCode)"
  Get-Content $err -ErrorAction SilentlyContinue | Select-Object -Last 20
} else {
  Write-Host "RENDER OK - window alive after 3s (no construction error)"
  $errtxt = Get-Content $err -Raw -ErrorAction SilentlyContinue
  if ($errtxt) { Write-Host "stderr:"; Write-Host $errtxt } else { Write-Host "stderr: (empty)" }
  $p.Kill()
  Write-Host "window closed."
}
